import textwrap
from collections import defaultdict
from pathlib import Path
from tempfile import NamedTemporaryFile
from typing import Dict, Iterable, List, Optional, Set, Tuple

import viktor as vkt


def _get_uploaded_file(value):
    """Support both `params.file_field` and `params.file_field.file` shapes."""
    if value is None:
        return None
    return getattr(value, "file", value)


def _safe_material_name(name: Optional[str]) -> str:
    name = (name or "").strip()
    return name if name else "<Unnamed material>"


def _material_names_from_relating_material(rel_mat) -> List[str]:
    """Extract material names from common IFC material relationship patterns."""
    if rel_mat is None:
        return []

    try:
        is_a = rel_mat.is_a
    except Exception:
        # Fallback to string
        return [_safe_material_name(str(rel_mat))]

    # IFC4/IFC2x3 patterns
    if is_a("IfcMaterial"):
        return [_safe_material_name(getattr(rel_mat, "Name", None))]

    if is_a("IfcMaterialList"):
        mats = getattr(rel_mat, "Materials", None) or []
        return [_safe_material_name(getattr(m, "Name", None)) for m in mats]

    if is_a("IfcMaterialLayerSetUsage"):
        return _material_names_from_relating_material(getattr(rel_mat, "ForLayerSet", None))

    if is_a("IfcMaterialLayerSet"):
        layers = getattr(rel_mat, "MaterialLayers", None) or []
        out = []
        for layer in layers:
            mat = getattr(layer, "Material", None)
            if mat:
                out.append(_safe_material_name(getattr(mat, "Name", None)))
        return out

    if is_a("IfcMaterialLayer"):
        mat = getattr(rel_mat, "Material", None)
        return [_safe_material_name(getattr(mat, "Name", None))] if mat else []

    if is_a("IfcMaterialProfileSetUsage"):
        return _material_names_from_relating_material(getattr(rel_mat, "ForProfileSet", None))

    if is_a("IfcMaterialProfileSet"):
        profiles = getattr(rel_mat, "MaterialProfiles", None) or []
        out = []
        for prof in profiles:
            mat = getattr(prof, "Material", None)
            if mat:
                out.append(_safe_material_name(getattr(mat, "Name", None)))
        return out

    if is_a("IfcMaterialProfile"):
        mat = getattr(rel_mat, "Material", None)
        return [_safe_material_name(getattr(mat, "Name", None))] if mat else []

    if is_a("IfcMaterialConstituentSet"):
        consts = getattr(rel_mat, "MaterialConstituents", None) or []
        out = []
        for c in consts:
            mat = getattr(c, "Material", None)
            if mat:
                out.append(_safe_material_name(getattr(mat, "Name", None)))
        return out

    if is_a("IfcMaterialConstituent"):
        mat = getattr(rel_mat, "Material", None)
        return [_safe_material_name(getattr(mat, "Name", None))] if mat else []

    # Fallback
    return [_safe_material_name(getattr(rel_mat, "Name", None) or str(rel_mat))]


def _get_type_object(element):
    """Return the relating type (IfcTypeObject) if present."""
    for rel in getattr(element, "IsDefinedBy", None) or []:
        if getattr(rel, "is_a", lambda *_: False)("IfcRelDefinesByType"):
            return getattr(rel, "RelatingType", None)
    return None


def _get_material_names(element) -> List[str]:
    """Get material names from an element and (if needed) its type."""
    names: Set[str] = set()

    def add_from_obj(obj):
        for assoc in getattr(obj, "HasAssociations", None) or []:
            if getattr(assoc, "is_a", lambda *_: False)("IfcRelAssociatesMaterial"):
                rel_mat = getattr(assoc, "RelatingMaterial", None)
                for n in _material_names_from_relating_material(rel_mat):
                    if n:
                        names.add(n)

    add_from_obj(element)

    if not names:
        type_obj = _get_type_object(element)
        if type_obj is not None:
            add_from_obj(type_obj)

    return sorted(names)


def _iter_element_quantities(element) -> Iterable:
    """Yield IfcPhysicalQuantity entries from IfcElementQuantity definitions."""
    for rel in getattr(element, "IsDefinedBy", None) or []:
        if not getattr(rel, "is_a", lambda *_: False)("IfcRelDefinesByProperties"):
            continue
        pdef = getattr(rel, "RelatingPropertyDefinition", None)
        if pdef is None:
            continue
        if getattr(pdef, "is_a", lambda *_: False)("IfcElementQuantity"):
            for q in getattr(pdef, "Quantities", None) or []:
                yield q


def _get_volume_from_quantities(element, preference: str) -> Optional[float]:
    """Try extracting a volume (float) from IfcQuantityVolume in element quantities."""
    # Collect all volume quantities
    candidates: Dict[str, float] = {}
    for q in _iter_element_quantities(element):
        if not getattr(q, "is_a", lambda *_: False)("IfcQuantityVolume"):
            continue
        name = (getattr(q, "Name", None) or "").strip()
        val = getattr(q, "VolumeValue", None)
        try:
            if val is None:
                continue
            candidates[name.lower()] = float(val)
        except Exception:
            continue

    if not candidates:
        return None

    pref = (preference or "Any").strip().lower()
    if pref != "any":
        # Exact matches are preferred
        if pref.lower() in candidates:
            return candidates[pref.lower()]

    # Common fallbacks
    for k in ("netvolume", "grossvolume", "volume"):
        if k in candidates:
            return candidates[k]

    # Anything
    return next(iter(candidates.values()), None)


def _try_get_length_scale_to_m(model) -> Optional[float]:
    """Return length scale factor to meters, if available in this IfcOpenShell build."""
    try:
        import ifcopenshell.util.unit

        return float(ifcopenshell.util.unit.calculate_unit_scale(model))
    except Exception:
        return None


def build_material_inventory(
    ifc_bytes: bytes,
    volume_preference: str = "NetVolume",
    include_unassigned: bool = True,
) -> Tuple[Dict[str, dict], dict]:
    """Return (inventory, meta).

    inventory format:
        { material_name: {
            'element_ids': set(int),
            'elements_with_volume': int,
            'total_volume_raw': float,
        }}
    """
    try:
        import ifcopenshell
    except Exception as e:
        raise vkt.UserError(
            "IfcOpenShell is not available. Add it to requirements.txt (if allowed in your environment)."
        ) from e

    tmp_path = None
    try:
        with NamedTemporaryFile(suffix=".ifc", delete=False) as tmp:
            tmp.write(ifc_bytes)
            tmp_path = Path(tmp.name)

        model = ifcopenshell.open(str(tmp_path))

        # Collect physical-ish elements
        elements = []
        for el in model.by_type("IfcElement"):
            # Exclude non-procurement entities
            if el.is_a("IfcOpeningElement") or el.is_a("IfcSpace"):
                continue
            elements.append(el)

        length_scale = _try_get_length_scale_to_m(model)

        inventory: Dict[str, dict] = defaultdict(
            lambda: {
                "element_ids": set(),
                "elements_with_volume": 0,
                "total_volume_raw": 0.0,
            }
        )

        total_elements = 0
        elements_with_any_material = 0
        elements_without_material = 0
        elements_with_volume = 0

        for el in elements:
            total_elements += 1

            mats = _get_material_names(el)
            if not mats:
                if not include_unassigned:
                    continue
                mats = ["<Unassigned>"]
                elements_without_material += 1
            else:
                elements_with_any_material += 1

            el_id = int(el.id())

            for mat in mats:
                inventory[mat]["element_ids"].add(el_id)

            # Volume attribution: only attribute to a material if there is exactly one
            # (otherwise we'd need layer thickness / constituent ratios).
            vol = _get_volume_from_quantities(el, preference=volume_preference)
            if vol is not None:
                elements_with_volume += 1
                if len(mats) == 1:
                    inventory[mats[0]]["total_volume_raw"] += float(vol)
                    inventory[mats[0]]["elements_with_volume"] += 1

        meta = {
            "schema": getattr(model, "schema", ""),
            "length_scale_to_m": length_scale,
            "total_elements_considered": total_elements,
            "elements_with_any_material": elements_with_any_material,
            "elements_without_material": elements_without_material,
            "elements_with_volume_any": elements_with_volume,
        }

        return inventory, meta

    finally:
        if tmp_path and tmp_path.exists():
            try:
                tmp_path.unlink(missing_ok=True)
            except Exception:
                pass


class Parametrization(vkt.Parametrization):
    main = vkt.Page("Material inventory", views=["materials_table"])
    main.inputs = vkt.Section("Inputs")
    main.inputs.intro = vkt.Text(
        textwrap.dedent(
            """\
            # Material Inventory Table (IFC)

            Upload an IFC file and generate a quick **bill of materials**:

            - Distinct materials in the model
            - Number of elements associated with each material
            - Total material volume **when the IFC contains quantity take-off (Qto) volumes**

            **Notes on volume**

            - The app reads `IfcElementQuantity` entries of type `IfcQuantityVolume` (e.g. `NetVolume`, `GrossVolume`).
            - If an element has **multiple materials** (layer sets / constituents), the element **is counted** for each material,
              but its volume is **not allocated** (to avoid incorrect splits).
            """
        )
    )

    main.inputs.ifc_file = vkt.FileField("IFC file")
    main.inputs.volume_preference = vkt.OptionField(
        "Volume preference (from Qto)",
        options=["NetVolume", "GrossVolume", "Any"],
        default="NetVolume",
    )
    main.inputs.include_unassigned = vkt.BooleanField(
        "Include '<Unassigned>' bucket", default=True
    )

    viewer = vkt.Page("IFC viewer", views=["ifc_view"])
    viewer.info = vkt.Section("Viewer")
    viewer.info.text = vkt.Text(
        "Open this page to visually inspect the uploaded IFC model (no calculations)."
    )


class Controller(vkt.Controller):
    parametrization = Parametrization

    @vkt.TableView("Materials table", duration_guess=5)
    def materials_table(self, params, **kwargs):
        ifc_file = _get_uploaded_file(params.main.inputs.ifc_file)
        if not ifc_file:
            raise vkt.UserError("Please upload an IFC file.")

        inventory, meta = build_material_inventory(
            ifc_bytes=ifc_file.getvalue(),
            volume_preference=params.main.inputs.volume_preference,
            include_unassigned=bool(params.main.inputs.include_unassigned),
        )

        length_scale = meta.get("length_scale_to_m")
        volume_scale_to_m3 = (length_scale ** 3) if length_scale else None

        rows = []
        for mat, rec in inventory.items():
            element_count = len(rec["element_ids"])
            vol_raw = float(rec["total_volume_raw"] or 0.0)

            # Show converted volume only as an additional hint.
            vol_m3 = vol_raw * volume_scale_to_m3 if volume_scale_to_m3 else None

            rows.append(
                [
                    mat,
                    element_count,
                    int(rec["elements_with_volume"] or 0),
                    round(vol_raw, 6) if rec["elements_with_volume"] else None,
                    round(vol_m3, 6) if (vol_m3 is not None and rec["elements_with_volume"]) else None,
                ]
            )

        # Sort: most elements first, then name
        rows.sort(key=lambda r: (-(r[1] or 0), r[0]))

        headers = [
            "Material",
            "Elements [#]",
            "Elements with volume [#]",
            "Total volume (raw units)",
            "Total volume (m³, inferred)",
        ]

        # Add a small footer row to clarify counts
        rows.append(
            [
                "---",
                meta.get("total_elements_considered", 0),
                meta.get("elements_with_volume_any", 0),
                None,
                None,
            ]
        )

        return vkt.TableResult(rows, column_headers=headers)

    @vkt.IFCView("IFC model")
    def ifc_view(self, params, **kwargs):
        ifc_file = _get_uploaded_file(params.main.inputs.ifc_file)
        if not ifc_file:
            raise vkt.UserError("Please upload an IFC file on the 'Material inventory' page.")
        return vkt.IFCResult(ifc_file)
